            return FfiConverterTypeFolderSyncSnapshot.lift(
    callWithHandle {
    uniffiRustCallWithError(KazeCoreException) { _status ->
    UniffiLib.uniffi_kazemail_core_fn_method_safeimapclient_examine_folder(
        it,
        
        FfiConverterString.lower(`fullPath`),_status)
}
    }
    )
    }
    

    
    /**
     * Returns all UIDs sorted descending (newest first) for Phase 2 chunked backfill.
